// verify-otp: check the code with ChinqIT, then create/refresh the Supabase auth
// user and set the (throwaway) password the client will immediately sign in with.
//
// Body: {
//   phone_number: string,          // E.164 without '+'
//   user_code:    string,          // the code the user typed
//   password:     string,          // random secret generated by the CLIENT; user never sees it
//   full_name?:   string,          // optional; captured on first sign-in
//   channel?:     'sms'|'whatsapp'
// }
//
// On success the client calls supabase.auth.signInWithPassword({ phone, password }).
// The profiles row + membership backfill are handled by the handle_new_user()
// trigger (0001_schema.sql), so this function does not touch them beyond full_name.
import { serve } from 'https://deno.land/std@0.177.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.39.7'
import { corsHeaders, CHINQIT_BASE, DEFAULT_CHANNEL } from '../_shared/cors.ts'

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })

  try {
    const { phone_number, user_code, password, full_name, channel } = await req.json()
    if (!phone_number || !user_code || !password) {
      throw new Error('phone_number, user_code and password are required')
    }

    const apiKey = Deno.env.get('CHINQIT_API_KEY')
    if (!apiKey) throw new Error('CHINQIT_API_KEY not configured')

    // 1) verify the code with ChinqIT
    const checkRes = await fetch(`${CHINQIT_BASE}/check`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-API-Key': apiKey },
      body: JSON.stringify({
        phoneNumber: phone_number,
        otp: user_code,
        channel: channel ?? DEFAULT_CHANNEL,
      }),
    })
    const checkData = await checkRes.json()
    console.log('ChinqIT /check response:', JSON.stringify(checkData))

    if (!checkData.verified) {
      return new Response(JSON.stringify({ error: 'invalid or expired code' }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 401,
      })
    }

    // 2) create or update the Supabase auth user (service role → bypasses RLS)
    const admin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    )

    const { data: list, error: listErr } = await admin.auth.admin.listUsers()
    if (listErr) throw listErr
    let user = list.users.find((u) => u.phone === phone_number)

    if (!user) {
      const { data: created, error: createErr } = await admin.auth.admin.createUser({
        phone: phone_number,
        password,
        phone_confirm: true,
        user_metadata: full_name ? { full_name } : undefined,
      })
      if (createErr) throw createErr
      user = created.user
      // handle_new_user() trigger has now created the profile + claimed memberships
    } else {
      const { error: updErr } = await admin.auth.admin.updateUserById(user.id, {
        password,
        ...(full_name ? { user_metadata: { full_name } } : {}),
      })
      if (updErr) throw updErr
    }

    // optional: keep full_name in profiles in sync when provided
    if (full_name && user) {
      await admin.from('profiles').update({ full_name }).eq('id', user.id)
    }

    return new Response(JSON.stringify({ success: true }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 200,
    })
  } catch (error) {
    console.error('verify-otp error:', error.message)
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 400,
    })
  }
})
